#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=5

# ── Helpers (this wizard's own; the library above stays untouched) ────────

# _secrets_on_repo: names of the secrets already on the repository, so a
# re-run can tell what is done and what is left.
_secrets_on_repo() {
  gh auth status >/dev/null 2>&1 || return 0
  gh secret list --json name -q '.[].name' 2>/dev/null | tr '\n' ' ' || true
  return 0
}

# ask_default KEY "Prompt" DEFAULT: like ask, but the default is computed here
# instead of read back from a file written by an earlier run.
ask_default() {
  local key="$1" prompt="$2" default="$3" input
  printf '  %s%s%s %s[Enter uses: %s]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$default" "$RESET"
  read -e -r input || true
  [[ -z "$input" ]] && input="$default"
  printf -v "$key" '%s' "$input"
}

# cert_report PATH PASSWORD: subject and expiry of a PKCS#12, warning when it
# is close to expiring. An expired certificate breaks releases months later
# with a signature error nobody traces back to the day it was set up.
cert_report() {
  local p12="$1" password="$2" details subject expiry expires_at days
  details=$(openssl pkcs12 -in "$p12" -passin "pass:$password" -clcerts -nokeys 2>/dev/null)
  if [[ -z "$details" ]]; then
    warn "openssl could not read $p12: wrong file, or wrong password"
    return 1
  fi
  subject=$(printf '%s' "$details" | openssl x509 -noout -subject -nameopt RFC2253 2>/dev/null | sed 's/^subject=//' || true)
  expiry=$(printf '%s' "$details" | openssl x509 -noout -enddate 2>/dev/null | sed 's/^notAfter=//' || true)
  say "Subject: ${subject:-unknown}"
  say "Expires: ${expiry:-unknown}"
  expires_at=$(date -d "$expiry" +%s 2>/dev/null || true)
  if [[ -n "$expires_at" ]]; then
    days=$(( (expires_at - $(date +%s)) / 86400 ))
    (( days < 60 )) && warn "only $days days left: renew it before it blocks a release"
  fi
  return 0
}

# _subject_of P12 PASSWORD: the certificate's subject, RFC 2253 form.
_subject_of() {
  openssl pkcs12 -in "$1" -passin "pass:$2" -clcerts -nokeys 2>/dev/null |
    openssl x509 -noout -subject -nameopt RFC2253 2>/dev/null || true
}

# identity_from_p12: the codesign identity as Apple formats it, read from the
# certificate itself: "Developer ID Application: Name (TEAMID)".
identity_from_p12() { _subject_of "$1" "$2" | sed -n 's/.*CN=\(.*\),OU=.*/\1/p'; }

# team_from_p12: the 10-character Team ID, which is the OU of that certificate.
team_from_p12() { _subject_of "$1" "$2" | sed -n 's/.*OU=\([A-Z0-9]*\).*/\1/p'; }

REPO_NAME=$(gh repo view --json nameWithOwner -q .nameWithOwner 2>/dev/null || echo "this repository")
SECRETS_ON_REPO=$(_secrets_on_repo)
already_set() { [[ " $SECRETS_ON_REPO " == *" $1 "* ]]; }

banner "Release signing — CD Catalog Premium"

# ── Stage 1: preflight ────────────────────────────────────────────────────
stage "Preflight: GitHub CLI and the repository"
say "The signed installers are built by .github/workflows/release.yml, which"
say "reads its certificates from the secrets of $REPO_NAME."
note "Both platforms are optional: without their secrets the same workflow"
note "still builds and uploads unsigned installers."
if [[ -n "$SECRETS_ON_REPO" ]]; then
  say "Already on the repository: $SECRETS_ON_REPO"
else
  warn "no repository secrets found — if gh is not installed or not logged in,"
  warn "values are only printed at the end and must be stored by hand"
  note "install and log in with: gh auth login"
fi
pause

# ── Stage 2: Apple certificate ────────────────────────────────────────────
stage "macOS: Developer ID certificate"
_apple_ready=""
if already_set APPLE_CERTIFICATE && ! confirm "Apple secrets are already on the repository. Replace them?"; then
  note "keeping the current Apple secrets"
  _apple_ready=1
elif confirm "Sign macOS builds? (needs a paid Apple Developer membership)"; then
  say "The certificate is a 'Developer ID Application' one. It lasts a year, so"
  say "this is also the stage to re-run when it expires."
  key_dir=""
  p12=""
  ask PKCS_PATH "Path to an existing .p12 (leave empty to create one here):"
  if [[ -n "$PKCS_PATH" ]]; then
    p12=$PKCS_PATH
    ask_secret APPLE_CERTIFICATE_PASSWORD "Password of that .p12:"
  else
    # Everything except the portal upload happens right here, so this works
    # from Linux: the private key never has to touch another machine.
    key_dir=$(mktemp -d) && chmod 700 "$key_dir"
    ask_secret APPLE_CERTIFICATE_PASSWORD "Choose a password for the new certificates (CI needs it):"
    step "Generating a private key and a certificate request…"
    openssl req -new -newkey rsa:2048 -keyout "$key_dir/devid.key" \
      -passout "pass:$APPLE_CERTIFICATE_PASSWORD" \
      -out "$key_dir/devid.certSigningRequest" \
      -subj "/CN=Developer ID Application" >/dev/null 2>&1
    say "Request written to $key_dir/devid.certSigningRequest"
    open_url "https://developer.apple.com/account/resources/certificates/list"
    step "Certificates → + → 'Developer ID: Application' → G2 Sub-CA"
    step "Upload $key_dir/devid.certSigningRequest and download the .cer"
    pause "Press Enter once the .cer is downloaded"
    ask CER_PATH "Path to the downloaded .cer:"
    if ! openssl x509 -inform DER -in "$CER_PATH" -out "$key_dir/devid.pem" 2>/dev/null; then
      cp "$CER_PATH" "$key_dir/devid.pem"
    fi
    p12="$key_dir/devid.p12"
    openssl pkcs12 -export -inkey "$key_dir/devid.key" \
      -passin "pass:$APPLE_CERTIFICATE_PASSWORD" -in "$key_dir/devid.pem" \
      -out "$p12" -passout "pass:$APPLE_CERTIFICATE_PASSWORD" \
      -name "Developer ID Application" >/dev/null 2>&1
    say "Built $p12"
  fi
  cert_report "$p12" "$APPLE_CERTIFICATE_PASSWORD"
  APPLE_CERTIFICATE=$(openssl base64 -A -in "$p12")
  set_secret APPLE_CERTIFICATE "$APPLE_CERTIFICATE"
  set_secret APPLE_CERTIFICATE_PASSWORD "$APPLE_CERTIFICATE_PASSWORD"
  # The keychain the runner builds lives for one job, so its password is
  # throwaway: generated rather than asked for.
  KEYCHAIN_PASSWORD=$(openssl rand -base64 24)
  set_secret KEYCHAIN_PASSWORD "$KEYCHAIN_PASSWORD"
  DETECTED_IDENTITY=$(identity_from_p12 "$p12" "$APPLE_CERTIFICATE_PASSWORD")
  DETECTED_TEAM=$(team_from_p12 "$p12" "$APPLE_CERTIFICATE_PASSWORD")
  ask_default APPLE_SIGNING_IDENTITY "codesign identity" "${DETECTED_IDENTITY:-Developer ID Application: Your Name (TEAMID)}"
  set_secret APPLE_SIGNING_IDENTITY "$APPLE_SIGNING_IDENTITY"
  _apple_ready=1
  if [[ -n "$key_dir" ]]; then
    say "The private key of the new certificate is in $key_dir"
    note "Save it somewhere safe: it is the only key that can renew the .p12."
    if confirm "Delete $key_dir now that the .p12 is built?"; then
      rm -rf "$key_dir"
      say "Deleted"
    fi
  fi
else
  SKIPPED+=("Apple secrets: macOS installers stay unsigned (Gatekeeper warns)")
  note "unsigned installers work; Gatekeeper warns on every install"
fi

# ── Stage 3: Apple notarization ───────────────────────────────────────────
stage "macOS: notarization credentials"
if [[ -n "$_apple_ready" ]]; then
  say "A signed app that was never notarized is still refused by Gatekeeper, so"
  say "without these three values the release job fails its own verification."
  open_url "https://account.apple.com/account/manage"
  step "Sign-In & Security → App-Specific Passwords → + → call it 'cd-catalog-ci'"
  ask APPLE_ID "Apple ID email:"
  ask_secret APPLE_PASSWORD "App-specific password (xxxx-xxxx-xxxx-xxxx):"
  ask_default APPLE_TEAM_ID "Team ID (10 characters)" "${DETECTED_TEAM:-ABCDE1234}"
  set_secret APPLE_ID "$APPLE_ID"
  set_secret APPLE_PASSWORD "$APPLE_PASSWORD"
  set_secret APPLE_TEAM_ID "$APPLE_TEAM_ID"
else
  SKIPPED+=("Apple notarization: without it Gatekeeper refuses the signed app")
  note "add the Apple certificate first (previous stage), then re-run"
fi

# ── Stage 4: Windows certificate ──────────────────────────────────────────
stage "Windows: code-signing certificate"
if already_set WINDOWS_CERTIFICATE && ! confirm "Windows secrets are already on the repository. Replace them?"; then
  note "keeping the current Windows secrets"
elif confirm "Sign Windows installers? (needs an OV or EV code-signing certificate)"; then
  say "Certificate authorities (DigiCert, Sectigo, …) sell these. You want a"
  say ".pfx file and its password."
  note "Azure Trusted Signing is not wired into this workflow: only a .pfx is."
  ask PFX_PATH "Path to the .pfx:"
  ask_secret WINDOWS_CERTIFICATE_PASSWORD "Password for that .pfx:"
  cert_report "$PFX_PATH" "$WINDOWS_CERTIFICATE_PASSWORD"
  WINDOWS_CERTIFICATE=$(openssl base64 -A -in "$PFX_PATH")
  set_secret WINDOWS_CERTIFICATE "$WINDOWS_CERTIFICATE"
  set_secret WINDOWS_CERTIFICATE_PASSWORD "$WINDOWS_CERTIFICATE_PASSWORD"
else
  SKIPPED+=("Windows secrets: installers stay unsigned (SmartScreen warns)")
  note "unsigned installers work; SmartScreen warns on every install"
fi

# ── Stage 5: what the workflow will find ──────────────────────────────────
stage "Verify: what the release workflow will find"
SECRETS_ON_REPO=$(_secrets_on_repo)
for name in APPLE_CERTIFICATE APPLE_CERTIFICATE_PASSWORD KEYCHAIN_PASSWORD \
            APPLE_SIGNING_IDENTITY APPLE_ID APPLE_PASSWORD APPLE_TEAM_ID \
            WINDOWS_CERTIFICATE WINDOWS_CERTIFICATE_PASSWORD; do
  if already_set "$name"; then
    printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$name"
  else
    printf '  %s·%s %s %s(not set)%s\n' "$DIM" "$RESET" "$name" "$DIM" "$RESET"
  fi
done
say ""
note "macOS installers build unsigned without the APPLE_* secrets;"
note "Windows installers do the same without the WINDOWS_* ones."
say ""
say "Build the installers from a tag, or by hand:"
note "  git tag v0.1.0 && git push origin v0.1.0"
note "  Actions → release → Run workflow"
say "The job proves the signature (codesign + spctl + stapler, Authenticode)"
say "and fails instead of uploading installers that only look signed."

finish
}

run_wizard "$@"; exit
